package com.edjoe.cluecase;

public enum AnimateClueTiers
{
	ALL("All tiers", 0),
	MEDIUM_PLUS("Medium and above", 2),
	HARD_PLUS("Hard and above", 3),
	ELITE_PLUS("Elite and above", 4),
	MASTER_ONLY("Master only", 5);

	private final String label;
	private final int minimumTier;

	AnimateClueTiers(String label, int minimumTier)
	{
		this.label = label;
		this.minimumTier = minimumTier;
	}

	boolean includes(int tier) { return tier >= minimumTier; }

	@Override
	public String toString() { return label; }
}

package com.edjoe.cluecase;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

@ConfigGroup(ClueCaseConfig.GROUP)
public interface ClueCaseConfig extends Config
{
	String GROUP = "cluecase";

	@ConfigItem(
		keyName = "animateClueTiers",
		name = "Animate clue tiers",
		description = "Choose the lowest clue tier that uses the case-opening animation.",
		position = 0
	)
	default AnimateClueTiers animateClueTiers() { return AnimateClueTiers.ALL; }

	@ConfigItem(
		keyName = "interactionControl",
		name = "Skip and close control",
		description = "Choose which input skips the animation and closes the result.",
		position = 1
	)
	default InteractionControl interactionControl() { return InteractionControl.BOTH; }

	@ConfigItem(
		keyName = "soundEffects",
		name = "Sound effects",
		description = "Play native game sounds during the casket animation and reward reel.",
		position = 2
	)
	default boolean soundEffects()
	{
		return true;
	}
}

package com.edjoe.cluecase;

import java.awt.Color;
import java.awt.BasicStroke;
import java.awt.AlphaComposite;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.GradientPaint;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.RenderingHints;
import java.awt.Shape;
import java.awt.geom.AffineTransform;
import java.awt.image.BufferedImage;
import java.awt.event.KeyEvent;
import java.awt.event.MouseEvent;
import java.io.IOException;
import java.io.InputStream;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Locale;
import java.util.concurrent.ThreadLocalRandom;
import javax.inject.Inject;
import javax.inject.Singleton;
import javax.imageio.ImageIO;
import net.runelite.api.gameval.ItemID;
import net.runelite.client.game.ItemManager;
import net.runelite.client.input.KeyListener;
import net.runelite.client.input.MouseListener;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

@Singleton
class ClueCaseOverlay extends Overlay implements KeyListener, MouseListener
{
	private static final int TILE_SIZE = 132;
	private static final int TILE_GAP = 12;
	private static final int ITEM_ICON_SIZE = 38;
	private static final int PANEL_MARGIN = 12;
	private static final int PANEL_WIDTH = 700;
	private static final int PANEL_HEIGHT = 400;
	private static final int REEL_ITEM_COUNT = 64;
	private static final int WINNING_INDEX = 52;
	private static final int CASKET_DROP_DURATION = 900;
	private static final int CASKET_LANDS_AT = 400;
	private static final int CASKET_OPENING_DURATION = 1_450;
	private static final int CASKET_LID_RELEASE_AT = 950;
	private static final int CASKET_SPRITE_FRAME_WIDTH = 48;
	private static final int CASKET_SPRITE_FRAME_HEIGHT = 48;
	private static final int CASKET_SPRITE_FRAME_COUNT = 6;
	private static final int CASKET_SPRITE_ANIMATION_DURATION = 250;
	private static final int CASKET_SPRITE_SCALE = 8;
	private static final int CASKET_SPRITE_Y_OFFSET = -5;
	private static final int CASKET_SPRITE_VISIBLE_BOTTOM = 43;
	private static final int REEL_DURATION = 4_000;
	private static final BufferedImage HARD_CASKET_OPENING_SHEET = loadCasketOpeningSheet("hard");
	private static final BufferedImage BEGINNER_CASKET_OPENING_SHEET = loadCasketOpeningSheet("beginner");
	private static final BufferedImage EASY_CASKET_OPENING_SHEET = loadCasketOpeningSheet("easy");
	private static final BufferedImage MEDIUM_CASKET_OPENING_SHEET = loadCasketOpeningSheet("medium");
	private static final BufferedImage ELITE_CASKET_OPENING_SHEET = loadCasketOpeningSheet("elite");
	private static final BufferedImage MASTER_CASKET_OPENING_SHEET = loadCasketOpeningSheet("master");

	private final ItemManager itemManager;
	private final ClueCaseConfig config;
	private final ClueCaseSounds sounds;
	private List<List<Loot>> reel = Collections.emptyList();
	private List<LootRarity> reelRarities = Collections.emptyList();
	private List<Loot> actualLoot = Collections.emptyList();
	private int casketItemId;
	private volatile long startedAt;
	private boolean active;
	private boolean awaitingLoot;
	private boolean rewardSoundPlayed;
	private volatile boolean animationComplete;
	private volatile boolean skipToResultRequested;
	private volatile boolean skippedToResult;
	private boolean spaceDown;
	private boolean consumeLeftGesture;
	private boolean dropSoundPlayed;
	private int lastBounceImpact;
	private int lastTickIndex;
	private double winningStopPoint = TILE_SIZE / 2.0;
	private Runnable onClose;

	@Inject
	ClueCaseOverlay(ClueCasePlugin plugin, ItemManager itemManager, ClueCaseConfig config,
		ClueCaseSounds sounds)
	{
		super(plugin);
		this.itemManager = itemManager;
		this.config = config;
		this.sounds = sounds;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
	}

	void start(List<Loot> loot, int casketItemId)
	{
		if (!active || !awaitingLoot || this.casketItemId != casketItemId)
		{
			begin(casketItemId);
		}
		actualLoot = Collections.unmodifiableList(new ArrayList<>(loot));
		this.casketItemId = casketItemId;
		reel = buildReel(actualLoot, casketItemId);
		reelRarities = buildReelRarities(actualLoot, casketItemId);
		winningStopPoint = chooseWinningStopPoint();
		awaitingLoot = false;
		if (skipToResultRequested)
		{
			skipToResult();
		}
	}

	void begin(int casketItemId)
	{
		this.casketItemId = casketItemId;
		reel = Collections.emptyList();
		reelRarities = Collections.emptyList();
		actualLoot = Collections.emptyList();
		startedAt = System.currentTimeMillis();
		active = true;
		awaitingLoot = true;
		rewardSoundPlayed = false;
		animationComplete = false;
		skipToResultRequested = false;
		skippedToResult = false;
		spaceDown = false;
		dropSoundPlayed = false;
		lastBounceImpact = 0;
		lastTickIndex = -1;
	}

	void setOnClose(Runnable onClose)
	{
		this.onClose = onClose;
	}

	boolean isActive()
	{
		return active;
	}

	void clear()
	{
		reel = Collections.emptyList();
		reelRarities = Collections.emptyList();
		actualLoot = Collections.emptyList();
		active = false;
		awaitingLoot = false;
		animationComplete = false;
		skipToResultRequested = false;
		skippedToResult = false;
		spaceDown = false;
		consumeLeftGesture = false;
		if (onClose != null)
		{
			onClose.run();
		}
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!active)
		{
			return null;
		}

		long elapsed = System.currentTimeMillis() - startedAt;
		int duration = REEL_DURATION;
		Rectangle clip = graphics.getClipBounds();
		int panelWidth = Math.min(PANEL_WIDTH, Math.max(TILE_SIZE + PANEL_MARGIN * 2, clip.width - 32));
		int panelHeight = Math.min(PANEL_HEIGHT, clip.height);
		int x = clip.x + (clip.width - panelWidth) / 2;
		int y = clip.y + (clip.height - panelHeight) / 2;
		int reelX = x + PANEL_MARGIN;
		int reelWidth = panelWidth - PANEL_MARGIN * 2;
		int reelY = y + (panelHeight - TILE_SIZE) / 2;
		drawFrame(graphics, x, y, panelWidth, panelHeight, reelY);
		if (elapsed < CASKET_DROP_DURATION)
		{
			if (!skippedToResult && elapsed >= CASKET_LANDS_AT && !dropSoundPlayed)
			{
				dropSoundPlayed = true;
				sounds.playDrop();
			}
			if (elapsed >= CASKET_LANDS_AT)
			{
				double impactProgress = Math.min(1.0, (elapsed - CASKET_LANDS_AT)
					/ (double) (CASKET_DROP_DURATION - CASKET_LANDS_AT));
				int bounceImpact = Math.min(2, (int) (impactProgress * 3.0));
				if (!skippedToResult && bounceImpact > lastBounceImpact)
				{
					lastBounceImpact = bounceImpact;
					sounds.playBounce();
				}
			}
			drawCasketDrop(graphics, x, y, panelWidth, panelHeight, elapsed);
			return null;
		}

		if (elapsed < CASKET_DROP_DURATION + CASKET_OPENING_DURATION)
		{
			drawCasketOpening(graphics, x, y, panelWidth, panelHeight, elapsed - CASKET_DROP_DURATION);
			return null;
		}

		elapsed -= CASKET_DROP_DURATION + CASKET_OPENING_DURATION;
		if (reel.isEmpty())
		{
			return null;
		}

		double progress = Math.min(1.0, elapsed / (double) duration);
		// Cubic ease-out: quick spin at first, then a satisfying slow-down.
		double eased = 1.0 - Math.pow(1.0 - progress, 3.0);
		double stopOffset = WINNING_INDEX * (TILE_SIZE + TILE_GAP)
			+ winningStopPoint - reelWidth / 2.0;
		double offset = eased * stopOffset;
		int tickIndex = (int) (offset / (TILE_SIZE + TILE_GAP));
		if (!skippedToResult && tickIndex != lastTickIndex && progress < 1.0)
		{
			lastTickIndex = tickIndex;
			sounds.playTick();
		}
		int firstIndex = Math.max(0, (int) (offset / (TILE_SIZE + TILE_GAP)) - 1);

		Shape previousClip = graphics.getClip();
		graphics.clipRect(reelX, reelY, reelWidth, TILE_SIZE);
		for (int index = firstIndex; index < reel.size(); index++)
		{
			int tileX = reelX + index * (TILE_SIZE + TILE_GAP) - (int) offset;
			if (tileX > reelX + reelWidth || tileX + TILE_SIZE < reelX)
			{
				continue;
			}
			drawRewardTile(graphics, reel.get(index), tileX, reelY, reelRarities.get(index));
		}
		graphics.setClip(previousClip);

		int centerX = reelX + reelWidth / 2;
		graphics.setColor(new Color(255, 205, 54));
		graphics.fillPolygon(new int[]{centerX - 10, centerX + 10, centerX},
			new int[]{reelY - 14, reelY - 14, reelY}, 3);
		graphics.fillPolygon(new int[]{centerX - 10, centerX + 10, centerX},
			new int[]{reelY + TILE_SIZE + 14, reelY + TILE_SIZE + 14, reelY + TILE_SIZE}, 3);

		if (progress >= 1.0)
		{
			animationComplete = true;
			if (!rewardSoundPlayed)
			{
				rewardSoundPlayed = true;
				sounds.playReward();
			}
			long settledFor = Math.max(0L, elapsed - duration);
			drawWinningShowcase(graphics, centerX, reelY + TILE_SIZE / 2, settledFor);
			int resultBaseline = reelY + TILE_SIZE + 88;
			drawResult(graphics, reelX, reelWidth, resultBaseline);
			drawDismissPrompt(graphics, reelX, reelWidth, resultBaseline + 24);
		}
		return null;
	}

	@Override
	public void keyPressed(KeyEvent event)
	{
		if (!active || !config.interactionControl().allowsSpace()
			|| event.getKeyCode() != KeyEvent.VK_SPACE || spaceDown)
		{
			return;
		}
		spaceDown = true;
		event.consume();
		handleAdvanceOrDismiss();
	}

	private void handleAdvanceOrDismiss()
	{
		if (animationComplete)
		{
			clear();
			return;
		}
		if (reel.isEmpty())
		{
			skipToResultRequested = true;
			return;
		}
		skipToResult();
	}

	@Override
	public void keyReleased(KeyEvent event)
	{
		if (event.getKeyCode() == KeyEvent.VK_SPACE)
		{
			spaceDown = false;
		}
	}

	@Override
	public void keyTyped(KeyEvent event)
	{
	}

	@Override
	public MouseEvent mousePressed(MouseEvent event)
	{
		if (!active || event.getButton() != MouseEvent.BUTTON1
			|| !config.interactionControl().allowsLeftClick())
		{
			return event;
		}
		handleAdvanceOrDismiss();
		consumeLeftGesture = true;
		event.consume();
		return event;
	}

	@Override
	public MouseEvent mouseReleased(MouseEvent event)
	{
		if (consumeLeftGesture)
		{
			consumeLeftGesture = false;
			event.consume();
		}
		return event;
	}

	@Override
	public MouseEvent mouseClicked(MouseEvent event)
	{
		if (consumeLeftGesture)
		{
			consumeLeftGesture = false;
			event.consume();
		}
		return event;
	}

	@Override
	public MouseEvent mouseEntered(MouseEvent event) { return event; }

	@Override
	public MouseEvent mouseExited(MouseEvent event) { return event; }

	@Override
	public MouseEvent mouseDragged(MouseEvent event)
	{
		if (consumeLeftGesture)
		{
			event.consume();
		}
		return event;
	}

	@Override
	public MouseEvent mouseMoved(MouseEvent event) { return event; }

	private void skipToResult()
	{
		// Set this first so a render already in progress cannot enqueue another
		// landing, opening, or reel sound after the skip input is received.
		skippedToResult = true;
		skipToResultRequested = false;
		dropSoundPlayed = true;
		lastBounceImpact = 2;
		startedAt = System.currentTimeMillis()
			- CASKET_DROP_DURATION - CASKET_OPENING_DURATION - REEL_DURATION;
	}

	private void drawWinningShowcase(Graphics2D graphics, int centerX, int centerY, long settledFor)
	{
		double progress = Math.min(1.0, settledFor / 320.0);
		double eased = 1.0 - Math.pow(1.0 - progress, 3.0);
		double scale = 1.0 + 0.62 * eased;
		int reelTileCenterX = (int) Math.round(centerX + TILE_SIZE / 2.0 - winningStopPoint);
		int showcaseCenterX = (int) Math.round(reelTileCenterX + (centerX - reelTileCenterX) * eased);
		int backdropWidth = (int) Math.round(TILE_SIZE * scale + 32);
		int backdropHeight = (int) Math.round(TILE_SIZE * scale + 32);

		graphics.setColor(new Color(10, 13, 19, (int) Math.round(175 * eased)));
		graphics.fillRoundRect(showcaseCenterX - backdropWidth / 2, centerY - backdropHeight / 2,
			backdropWidth, backdropHeight, 18, 18);

		Graphics2D showcaseGraphics = (Graphics2D) graphics.create();
		try
		{
			showcaseGraphics.translate(showcaseCenterX, centerY);
			showcaseGraphics.scale(scale, scale);
			showcaseGraphics.translate(-showcaseCenterX, -centerY);
			drawRewardTile(showcaseGraphics, actualLoot,
				showcaseCenterX - TILE_SIZE / 2, centerY - TILE_SIZE / 2);
		}
		finally
		{
			showcaseGraphics.dispose();
		}
	}

	private void drawCasketDrop(Graphics2D graphics, int x, int y, int width, int height, long elapsed)
	{
		BufferedImage openingSheet = getCasketOpeningSheet();
		boolean useCasketSheet = openingSheet != null;
		BufferedImage casket = useCasketSheet
			? openingSheet : itemManager.getImage(casketItemId, 1, false);
		if (casket == null)
		{
			return;
		}
		int sourceWidth = useCasketSheet ? CASKET_SPRITE_FRAME_WIDTH : casket.getWidth();
		int sourceHeight = useCasketSheet ? CASKET_SPRITE_FRAME_HEIGHT : casket.getHeight();

		double fallProgress = Math.min(1.0, elapsed / (double) CASKET_LANDS_AT);
		double acceleratedFall = fallProgress * fallProgress;
		double impactProgress = Math.max(0.0,
			Math.min(1.0, (elapsed - CASKET_LANDS_AT) / (double) (CASKET_DROP_DURATION - CASKET_LANDS_AT)));
		double squashProgress = Math.max(0.0,
			Math.min(1.0, (elapsed - CASKET_LANDS_AT) / 180.0));
		int normalWidth = useCasketSheet
			? CASKET_SPRITE_FRAME_WIDTH * CASKET_SPRITE_SCALE : 270;
		int normalHeight = useCasketSheet
			? CASKET_SPRITE_FRAME_HEIGHT * CASKET_SPRITE_SCALE : 270;
		int squash = (int) Math.round(Math.sin(squashProgress * Math.PI) * 24.0);
		int imageWidth = normalWidth + squash;
		int imageHeight = normalHeight - squash;
		int landingY = y + (height - normalHeight) / 2;
		int startY = y - normalHeight;
		int imageY = (int) Math.round(startY + (landingY - startY) * acceleratedFall) + squash / 2
			+ (useCasketSheet ? CASKET_SPRITE_Y_OFFSET * CASKET_SPRITE_SCALE : 0);
		int imageX = x + (width - imageWidth) / 2;

		Graphics2D dropGraphics = (Graphics2D) graphics.create();
		try
		{
			dropGraphics.setRenderingHint(RenderingHints.KEY_INTERPOLATION,
				RenderingHints.VALUE_INTERPOLATION_NEAREST_NEIGHBOR);
			if (impactProgress > 0.0)
			{
				double angle = Math.sin(impactProgress * Math.PI * 3.0)
					* Math.toRadians(9.0) * Math.pow(1.0 - impactProgress, 0.55);
				// Rock around whichever bottom corner is currently planted.
				double pivotX = angle > 0.0 ? imageX + imageWidth : imageX;
				double pivotY = imageY + imageHeight;
				AffineTransform originalTransform = dropGraphics.getTransform();
				dropGraphics.rotate(angle, pivotX, pivotY);
				dropGraphics.drawImage(casket,
					imageX, imageY, imageX + imageWidth, imageY + imageHeight,
					0, 0, sourceWidth, sourceHeight, null);
				dropGraphics.setTransform(originalTransform);
			}
			else
			{
				dropGraphics.drawImage(casket,
					imageX, imageY, imageX + imageWidth, imageY + imageHeight,
					0, 0, sourceWidth, sourceHeight, null);
			}
			if (impactProgress > 0.0)
			{
				int ringWidth = (int) Math.round(90 + squashProgress * 280);
				int alpha = (int) Math.round(130 * (1.0 - squashProgress));
				int casketBottom = useCasketSheet
					? landingY + (CASKET_SPRITE_Y_OFFSET + CASKET_SPRITE_VISIBLE_BOTTOM)
						* CASKET_SPRITE_SCALE
					: landingY + normalHeight;
				dropGraphics.setColor(new Color(255, 205, 54, alpha));
				dropGraphics.setStroke(new BasicStroke(4f));
				dropGraphics.drawOval(x + width / 2 - ringWidth / 2,
					casketBottom - 24, ringWidth, Math.max(8, ringWidth / 8));
			}
		}
		finally
		{
			dropGraphics.dispose();
		}
	}

	private void drawCasketOpening(Graphics2D graphics, int x, int y, int width, int height, long elapsed)
	{
		BufferedImage openingSheet = getCasketOpeningSheet();
		if (openingSheet != null)
		{
			drawSpriteCasketOpening(graphics, x, y, width, height, elapsed, openingSheet);
			return;
		}

		drawLegacyCasketOpening(graphics, x, y, width, height, elapsed);
	}

	private void drawSpriteCasketOpening(Graphics2D graphics, int x, int y, int width, int height,
		long elapsed, BufferedImage openingSheet)
	{
		long animationElapsed = Math.max(0L, elapsed - CASKET_LID_RELEASE_AT);
		int frame = Math.min(CASKET_SPRITE_FRAME_COUNT - 1,
			(int) (animationElapsed * CASKET_SPRITE_FRAME_COUNT
				/ CASKET_SPRITE_ANIMATION_DURATION));
		double opening = frame / (double) (CASKET_SPRITE_FRAME_COUNT - 1);
		double fade = Math.max(0.0, Math.min(1.0, (elapsed - 1_300.0) / 150.0));
		int shake = elapsed >= 350 && elapsed < CASKET_LID_RELEASE_AT
			? (int) Math.round(Math.sin(elapsed * 0.075) * (2.0 + (elapsed - 350) / 100.0)) : 0;
		int imageWidth = CASKET_SPRITE_FRAME_WIDTH * CASKET_SPRITE_SCALE;
		int imageHeight = CASKET_SPRITE_FRAME_HEIGHT * CASKET_SPRITE_SCALE;
		int imageX = x + (width - imageWidth) / 2 + shake;
		int imageY = y + (height - imageHeight) / 2
			+ CASKET_SPRITE_Y_OFFSET * CASKET_SPRITE_SCALE;

		Graphics2D openingGraphics = (Graphics2D) graphics.create();
		try
		{
			openingGraphics.setRenderingHint(RenderingHints.KEY_INTERPOLATION,
				RenderingHints.VALUE_INTERPOLATION_NEAREST_NEIGHBOR);
			openingGraphics.setComposite(AlphaComposite.SrcOver.derive((float) (1.0 - fade)));

			if (opening > 0.0)
			{
				int flashAlpha = (int) Math.round(150 * opening);
				openingGraphics.setColor(new Color(255, 232, 145, flashAlpha));
				int burst = (int) Math.round(40
					+ opening * (Math.max(imageWidth, imageHeight) - 6));
				openingGraphics.fillOval(x + width / 2 - burst / 2,
					y + height / 2 - burst / 2, burst, burst);
			}

			int sourceX = frame * CASKET_SPRITE_FRAME_WIDTH;
			openingGraphics.drawImage(openingSheet,
				imageX, imageY, imageX + imageWidth, imageY + imageHeight,
				sourceX, 0, sourceX + CASKET_SPRITE_FRAME_WIDTH,
				CASKET_SPRITE_FRAME_HEIGHT, null);
		}
		finally
		{
			openingGraphics.dispose();
		}
	}

	private void drawLegacyCasketOpening(Graphics2D graphics, int x, int y, int width, int height,
		long elapsed)
	{
		BufferedImage casket = itemManager.getImage(casketItemId, 1, false);
		if (casket == null)
		{
			return;
		}

		double opening = Math.max(0.0, Math.min(1.0, (elapsed - CASKET_LID_RELEASE_AT) / 250.0));
		double fade = Math.max(0.0, Math.min(1.0, (elapsed - 1_200.0) / 250.0));
		int shake = elapsed >= 350 && elapsed < CASKET_LID_RELEASE_AT
			? (int) Math.round(Math.sin(elapsed * 0.075) * (2.0 + (elapsed - 350) / 180.0)) : 0;
		int imageSize = 270;
		int imageX = x + (width - imageSize) / 2 + shake;
		int imageY = y + (height - imageSize) / 2;

		Graphics2D openingGraphics = (Graphics2D) graphics.create();
		try
		{
			openingGraphics.setRenderingHint(RenderingHints.KEY_INTERPOLATION,
				RenderingHints.VALUE_INTERPOLATION_NEAREST_NEIGHBOR);
			openingGraphics.setComposite(AlphaComposite.SrcOver.derive((float) (1.0 - fade)));

			int glowSize = imageSize + 34;
			int glowAlpha = (int) (55 + opening * 110);
			openingGraphics.setColor(new Color(255, 205, 54, glowAlpha));
			openingGraphics.fillOval(imageX - 17, imageY - 17, glowSize, glowSize);

			int sourceWidth = casket.getWidth();
			int sourceHeight = casket.getHeight();
			int lidCut = Math.max(1, sourceHeight / 2);
			int destinationCut = imageY + imageSize / 2;
			// Keep the body planted while the upper half lifts to sell the opening.
			openingGraphics.drawImage(casket, imageX, destinationCut,
				imageX + imageSize, imageY + imageSize,
				0, lidCut, sourceWidth, sourceHeight, null);
			int lidLift = (int) Math.round(opening * imageSize * 0.23);
			int lidSpread = (int) Math.round(opening * imageSize * 0.07);
			openingGraphics.drawImage(casket, imageX - lidSpread, imageY - lidLift,
				imageX + imageSize + lidSpread, destinationCut - lidLift,
				0, 0, sourceWidth, lidCut, null);
		}
		finally
		{
			openingGraphics.dispose();
		}

		if (opening > 0.0)
		{
			int flashAlpha = (int) Math.round(150 * opening * (1.0 - fade));
			graphics.setColor(new Color(255, 232, 145, flashAlpha));
			int burst = (int) Math.round(40 + opening * 150);
			graphics.fillOval(x + width / 2 - burst / 2, y + height / 2 - burst / 2, burst, burst);
		}
	}

	private BufferedImage getCasketOpeningSheet()
	{
		switch (casketItemId)
		{
			case ItemID.TRAIL_REWARD_CASKET_BEGINNER: return BEGINNER_CASKET_OPENING_SHEET;
			case ItemID.TRAIL_REWARD_CASKET_EASY: return EASY_CASKET_OPENING_SHEET;
			case ItemID.TRAIL_REWARD_CASKET_MEDIUM: return MEDIUM_CASKET_OPENING_SHEET;
			case ItemID.TRAIL_REWARD_CASKET_HARD: return HARD_CASKET_OPENING_SHEET;
			case ItemID.TRAIL_REWARD_CASKET_ELITE: return ELITE_CASKET_OPENING_SHEET;
			case ItemID.TRAIL_REWARD_CASKET_MASTER: return MASTER_CASKET_OPENING_SHEET;
			default: return null;
		}
	}

	private static BufferedImage loadCasketOpeningSheet(String tier)
	{
		try (InputStream stream = ClueCaseOverlay.class.getResourceAsStream(
			"/reward-casket-" + tier + "-sprite-sheet.png"))
		{
			return stream == null ? null : ImageIO.read(stream);
		}
		catch (IOException ex)
		{
			return null;
		}
	}

	private List<List<Loot>> buildReel(List<Loot> winningLoot, int casketItemId)
	{
		List<List<Loot>> items = new ArrayList<>();
		for (int index = 0; index < REEL_ITEM_COUNT; index++)
		{
			items.add(ClueLootSimulator.generate(casketItemId, rollCounterStrikeRarity()));
		}
		items.set(WINNING_INDEX, winningLoot);
		return items;
	}

	private List<LootRarity> buildReelRarities(List<Loot> winningLoot, int casketItemId)
	{
		List<LootRarity> rarities = new ArrayList<>(REEL_ITEM_COUNT);
		for (int index = 0; index < REEL_ITEM_COUNT; index++)
		{
			rarities.add(ClueLootSimulator.rarityFor(reel.get(index), casketItemId));
		}
		rarities.set(WINNING_INDEX, ClueLootSimulator.rarityFor(winningLoot, casketItemId));
		return rarities;
	}

	static LootRarity rollCounterStrikeRarity()
	{
		double roll = ThreadLocalRandom.current().nextDouble();
		if (roll < 0.79923)
		{
			return LootRarity.MIL_SPEC;
		}
		if (roll < 0.95908)
		{
			return LootRarity.RESTRICTED;
		}
		if (roll < 0.99105)
		{
			return LootRarity.CLASSIFIED;
		}
		if (roll < 0.99744)
		{
			return LootRarity.COVERT;
		}
		return LootRarity.RARE_SPECIAL;
	}

	private static double chooseWinningStopPoint()
	{
		return ThreadLocalRandom.current().nextDouble(3.0, TILE_SIZE - 3.0);
	}

	private void drawFrame(Graphics2D graphics, int x, int y, int width, int height, int reelY)
	{
		graphics.setColor(new Color(8, 11, 17, 150));
		graphics.fillRoundRect(x - 5, y - 5, width + 10, height + 10, 20, 20);
		graphics.setColor(new Color(18, 22, 31, 245));
		graphics.fillRoundRect(x, y, width, height, 16, 16);
		graphics.setColor(new Color(66, 81, 108));
		graphics.setStroke(new BasicStroke(1.5f));
		graphics.drawRoundRect(x, y, width - 1, height - 1, 16, 16);
		graphics.setColor(new Color(45, 57, 79));
		graphics.fillRoundRect(x + PANEL_MARGIN, reelY - 8,
			width - PANEL_MARGIN * 2, TILE_SIZE + 16, 10, 10);
	}

	private void drawTile(Graphics2D graphics, Loot loot, int x, int y)
	{
		drawTile(graphics, loot, x, y,
			ClueLootSimulator.rarityFor(Collections.singletonList(loot), casketItemId));
	}

	private void drawTile(Graphics2D graphics, Loot loot, int x, int y, LootRarity rarity)
	{
		Color rarityColor = rarity.getColor();
		drawTileFrame(graphics, x, y, rarityColor);
		BufferedImage image = itemManager.getImage(loot.getItemId(), loot.getQuantity(), true);
		if (image != null)
		{
			int imageSize = ITEM_ICON_SIZE;
			Object interpolation = graphics.getRenderingHint(RenderingHints.KEY_INTERPOLATION);
			graphics.setRenderingHint(RenderingHints.KEY_INTERPOLATION,
				RenderingHints.VALUE_INTERPOLATION_NEAREST_NEIGHBOR);
			graphics.drawImage(image, x + (TILE_SIZE - imageSize) / 2,
				y + (TILE_SIZE - 24 - imageSize) / 2,
				imageSize, imageSize, null);
			if (interpolation != null)
			{
				graphics.setRenderingHint(RenderingHints.KEY_INTERPOLATION, interpolation);
			}
		}

		String name = itemManager.getItemComposition(loot.getItemId()).getName();
		if (name.length() > 15)
		{
			name = name.substring(0, 14) + "…";
		}
		FontMetrics metrics = graphics.getFontMetrics();
		graphics.setColor(Color.WHITE);
		graphics.drawString(name, x + (TILE_SIZE - metrics.stringWidth(name)) / 2,
			y + TILE_SIZE - 10);
	}

	private void drawRewardTile(Graphics2D graphics, List<Loot> rewards, int x, int y)
	{
		drawRewardTile(graphics, rewards, x, y,
			ClueLootSimulator.rarityFor(rewards, casketItemId));
	}

	private void drawRewardTile(Graphics2D graphics, List<Loot> rewards, int x, int y,
		LootRarity rarity)
	{
		if (rewards.isEmpty())
		{
			return;
		}
		if (rewards.size() == 1)
		{
			drawTile(graphics, rewards.get(0), x, y, rarity);
			return;
		}

		Color rarityColor = rarity.getColor();
		drawTileFrame(graphics, x, y, rarityColor);
		int columns = (int) Math.ceil(Math.sqrt(rewards.size()));
		int rows = (int) Math.ceil(rewards.size() / (double) columns);
		int gridPadding = 8;
		int contentHeight = TILE_SIZE - 30;
		int contentWidth = TILE_SIZE - gridPadding * 2;
		int cellWidth = contentWidth / columns;
		int cellHeight = contentHeight / rows;
		int imageSize = ITEM_ICON_SIZE;

		Object interpolation = graphics.getRenderingHint(RenderingHints.KEY_INTERPOLATION);
		graphics.setRenderingHint(RenderingHints.KEY_INTERPOLATION,
			RenderingHints.VALUE_INTERPOLATION_NEAREST_NEIGHBOR);
		for (int index = 0; index < rewards.size(); index++)
		{
			Loot reward = rewards.get(index);
			BufferedImage image = itemManager.getImage(reward.getItemId(), reward.getQuantity(), true);
			if (image == null)
			{
				continue;
			}

			int column = index % columns;
			int row = index / columns;
			int imageX = x + gridPadding + column * cellWidth + (cellWidth - imageSize) / 2;
			int imageY = y + 3 + row * cellHeight + (cellHeight - imageSize) / 2;
			graphics.drawImage(image, imageX, imageY, imageSize, imageSize, null);
		}
		if (interpolation != null)
		{
			graphics.setRenderingHint(RenderingHints.KEY_INTERPOLATION, interpolation);
		}

		long totalValue = 0L;
		boolean hasUnpricedItem = false;
		for (Loot reward : rewards)
		{
			long itemPrice = itemManager.getItemPrice(reward.getItemId());
			if (itemPrice <= 0)
			{
				hasUnpricedItem = true;
			}
			else
			{
				totalValue += itemPrice * reward.getQuantity();
			}
		}
		String label = totalValue == 0L && hasUnpricedItem
			? "Untradeable"
			: formatGp(totalValue, hasUnpricedItem);
		FontMetrics metrics = graphics.getFontMetrics();
		graphics.setColor(new Color(255, 224, 112));
		graphics.drawString(label, x + (TILE_SIZE - metrics.stringWidth(label)) / 2,
			y + TILE_SIZE - 8);
	}

	private static String formatGp(long value, boolean partialValue)
	{
		String suffix = partialValue ? "+ gp" : " gp";
		if (value >= 1_000_000_000L)
		{
			return String.format(Locale.US, "%.2fB%s", value / 1_000_000_000.0, suffix);
		}
		if (value >= 1_000_000L)
		{
			return String.format(Locale.US, "%.2fM%s", value / 1_000_000.0, suffix);
		}
		if (value >= 1_000L)
		{
			return String.format(Locale.US, "%.1fK%s", value / 1_000.0, suffix);
		}
		return String.format(Locale.US, "%,d%s", value, suffix);
	}

	private static void drawTileFrame(Graphics2D graphics, int x, int y, Color borderColor)
	{
		Graphics2D tileGraphics = (Graphics2D) graphics.create();
		try
		{
			tileGraphics.setRenderingHint(RenderingHints.KEY_ANTIALIASING,
				RenderingHints.VALUE_ANTIALIAS_ON);

			// Layered translucent outlines give the rarity colour a soft bloom.
			tileGraphics.setColor(new Color(borderColor.getRed(), borderColor.getGreen(),
				borderColor.getBlue(), 35));
			tileGraphics.setStroke(new BasicStroke(9f));
			tileGraphics.drawRoundRect(x + 4, y + 4, TILE_SIZE - 8, TILE_SIZE - 8, 9, 9);
			tileGraphics.setColor(new Color(borderColor.getRed(), borderColor.getGreen(),
				borderColor.getBlue(), 75));
			tileGraphics.setStroke(new BasicStroke(5f));
			tileGraphics.drawRoundRect(x + 2, y + 2, TILE_SIZE - 4, TILE_SIZE - 4, 8, 8);

			tileGraphics.setPaint(new GradientPaint(x, y, new Color(48, 59, 80),
				x, y + TILE_SIZE, blend(new Color(24, 29, 40), borderColor, 0.28f)));
			tileGraphics.fillRoundRect(x + 2, y + 2, TILE_SIZE - 4, TILE_SIZE - 4, 7, 7);

			// A saturated lower accent makes the tier recognizable even behind icons.
			tileGraphics.setColor(new Color(borderColor.getRed(), borderColor.getGreen(),
				borderColor.getBlue(), 115));
			tileGraphics.fillRect(x + 3, y + TILE_SIZE - 17, TILE_SIZE - 6, 14);
			tileGraphics.setColor(borderColor);
			tileGraphics.setStroke(new BasicStroke(3f));
			tileGraphics.drawRoundRect(x + 1, y + 1, TILE_SIZE - 2, TILE_SIZE - 2, 8, 8);
		}
		finally
		{
			tileGraphics.dispose();
		}
	}

	private static Color blend(Color base, Color accent, float accentAmount)
	{
		float baseAmount = 1f - accentAmount;
		return new Color(
			Math.round(base.getRed() * baseAmount + accent.getRed() * accentAmount),
			Math.round(base.getGreen() * baseAmount + accent.getGreen() * accentAmount),
			Math.round(base.getBlue() * baseAmount + accent.getBlue() * accentAmount));
	}

	private void drawResult(Graphics2D graphics, int x, int width, int baseline)
	{
		StringBuilder result = new StringBuilder("Received: ");
		for (int index = 0; index < actualLoot.size(); index++)
		{
			Loot loot = actualLoot.get(index);
			if (index > 0)
			{
				result.append(", ");
			}
			result.append(itemManager.getItemComposition(loot.getItemId()).getName());
			if (loot.getQuantity() > 1)
			{
				result.append(" x").append(loot.getQuantity());
			}
		}
		FontMetrics metrics = graphics.getFontMetrics();
		graphics.setColor(new Color(255, 224, 112));
		graphics.drawString(result.toString(), x + (width - metrics.stringWidth(result.toString())) / 2, baseline);
	}

	private void drawDismissPrompt(Graphics2D graphics, int x, int width, int baseline)
	{
		boolean space = config.interactionControl().allowsSpace();
		boolean click = config.interactionControl().allowsLeftClick();
		String prompt;
		if (space && click)
		{
			prompt = "Press SPACE or left-click to close";
		}
		else if (space)
		{
			prompt = "Press SPACE to close";
		}
		else
		{
			prompt = "Left-click to close";
		}
		FontMetrics metrics = graphics.getFontMetrics();
		graphics.setColor(new Color(176, 195, 217));
		graphics.drawString(prompt, x + (width - metrics.stringWidth(prompt)) / 2, baseline);
	}
}

package com.edjoe.cluecase;

import com.google.inject.Provides;
import java.util.ArrayList;
import java.util.List;
import java.util.Locale;
import javax.inject.Inject;
import javax.inject.Named;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.ItemContainer;
import net.runelite.api.events.ClientTick;
import net.runelite.api.events.CommandExecuted;
import net.runelite.api.events.MenuOptionClicked;
import net.runelite.api.events.WidgetLoaded;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.input.KeyManager;
import net.runelite.client.input.MouseManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;

@PluginDescriptor(
	name = "Clue Case Opening",
	description = "Shows a CS-style reward reel after you open a clue casket.",
	tags = {"clue", "casket", "loot", "rewards", "animation"}
)
@Slf4j
public class ClueCasePlugin extends Plugin
{
	private static final long OPEN_RESULT_TIMEOUT_MILLIS = 5_000L;

	@Inject
	private Client client;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private KeyManager keyManager;

	@Inject
	private MouseManager mouseManager;

	@Inject
	private ClueCaseConfig config;

	@Inject
	@Named("developerMode")
	private boolean developerMode;

	@Inject
	private ClueCaseOverlay overlay;

	private long casketOpenedAt;
	private int openedCasketItemId;
	private boolean pendingCasketOpen;
	private boolean rewardScreenLoaded;
	private final List<Widget> hiddenRewardWidgets = new ArrayList<>();
	private Widget hiddenNotificationWidget;

	@Provides
	ClueCaseConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(ClueCaseConfig.class);
	}

	@Override
	protected void startUp()
	{
		overlayManager.add(overlay);
		keyManager.registerKeyListener(overlay);
		mouseManager.registerMouseListener(overlay);
		overlay.setOnClose(this::restoreHiddenWidgets);
		log.debug("Clue Case Opening started");
	}

	@Override
	protected void shutDown()
	{
		log.debug("Clue Case Opening shutting down");
		overlayManager.remove(overlay);
		keyManager.unregisterKeyListener(overlay);
		mouseManager.unregisterMouseListener(overlay);
		clearPendingOpen();
		overlay.clear();
	}

	@Subscribe
	public void onMenuOptionClicked(MenuOptionClicked event)
	{
		if (!event.getMenuOption().toLowerCase(Locale.ROOT).startsWith("open"))
		{
			return;
		}

		boolean clueCasket = isClueCasket(event.getItemId());
		log.debug("Open click received: itemId={}, clueCasket={}", event.getItemId(), clueCasket);
		if (!clueCasket)
		{
			return;
		}
		if (!config.animateClueTiers().includes(clueTier(event.getItemId())))
		{
			log.debug("Skipping animation for excluded clue tier: itemId={}", event.getItemId());
			return;
		}

		casketOpenedAt = System.currentTimeMillis();
		openedCasketItemId = event.getItemId();
		pendingCasketOpen = true;
		rewardScreenLoaded = false;
		log.debug("Awaiting reward screen for casket itemId={}", openedCasketItemId);
	}

	@Subscribe
	public void onWidgetLoaded(WidgetLoaded event)
	{
		if (event.getGroupId() == InterfaceID.NOTIFICATION_DISPLAY && overlay.isActive())
		{
			hideNotificationWidget();
			return;
		}
		if (event.getGroupId() != InterfaceID.TRAIL_REWARDSCREEN || !pendingCasketOpen)
		{
			return;
		}
		hideRewardWidget();
		rewardScreenLoaded = true;
		overlay.begin(openedCasketItemId);
		log.debug("Reward screen confirmed for casket itemId={}", openedCasketItemId);
		tryStartFromRewardContainer();
	}

	@Subscribe
	public void onClientTick(ClientTick event)
	{
		if (!pendingCasketOpen)
		{
			return;
		}
		if (System.currentTimeMillis() - casketOpenedAt > OPEN_RESULT_TIMEOUT_MILLIS)
		{
			log.debug("Casket reward capture timed out");
			clearPendingOpen();
			overlay.clear();
			return;
		}
		if (rewardScreenLoaded)
		{
			tryStartFromRewardContainer();
		}
	}

	@Subscribe
	public void onCommandExecuted(CommandExecuted event)
	{
		if (!developerMode || !event.getCommand().equalsIgnoreCase("cluecase"))
		{
			return;
		}

		String tier = event.getArguments().length == 0 ? "easy" : event.getArguments()[0].toLowerCase(Locale.ROOT);
		int casketItemId = casketItemIdForTier(tier);
		if (casketItemId == -1)
		{
			log.debug("Unknown clue-case preview tier '{}'; use beginner, easy, medium, hard, elite, or master", tier);
			return;
		}

		List<Loot> simulatedLoot = ClueLootSimulator.generate(casketItemId);
		log.debug("Starting developer preview for {} clue with {} reward item types", tier, simulatedLoot.size());
		overlay.start(simulatedLoot, casketItemId);
	}

	private static int casketItemIdForTier(String tier)
	{
		switch (tier)
		{
			case "beginner": return ItemID.TRAIL_REWARD_CASKET_BEGINNER;
			case "easy": return ItemID.TRAIL_REWARD_CASKET_EASY;
			case "medium": return ItemID.TRAIL_REWARD_CASKET_MEDIUM;
			case "hard": return ItemID.TRAIL_REWARD_CASKET_HARD;
			case "elite": return ItemID.TRAIL_REWARD_CASKET_ELITE;
			case "master": return ItemID.TRAIL_REWARD_CASKET_MASTER;
			default: return -1;
		}
	}

	private void tryStartFromRewardContainer()
	{
		ItemContainer rewards = client.getItemContainer(net.runelite.api.gameval.InventoryID.TRAIL_REWARDINV);
		List<Loot> loot = lootFromContainer(rewards);
		if (loot.isEmpty())
		{
			return;
		}
		log.debug("Starting reward overlay from authorized clue reward dialog");
		int casketItemId = openedCasketItemId;
		clearPendingOpen();
		overlay.start(loot, casketItemId);
	}

	private void clearPendingOpen()
	{
		pendingCasketOpen = false;
		rewardScreenLoaded = false;
		openedCasketItemId = 0;
		casketOpenedAt = 0L;
	}

	private void hideRewardWidget()
	{
		hiddenRewardWidgets.clear();
		for (int childId = 0; childId <= 4; childId++)
		{
			Widget widget = client.getWidget(InterfaceID.TRAIL_REWARDSCREEN, childId);
			if (widget != null && !widget.isHidden())
			{
				widget.setHidden(true);
				hiddenRewardWidgets.add(widget);
			}
		}
	}

	private void unhideRewardWidget()
	{
		for (Widget widget : hiddenRewardWidgets)
		{
			widget.setHidden(false);
		}
		hiddenRewardWidgets.clear();
	}

	private void hideNotificationWidget()
	{
		Widget widget = client.getWidget(InterfaceID.NotificationDisplay.UNIVERSE);
		if (widget == null)
		{
			return;
		}
		widget.setHidden(true);
		hiddenNotificationWidget = widget;
	}

	private void restoreHiddenWidgets()
	{
		unhideRewardWidget();
		if (hiddenNotificationWidget != null)
		{
			hiddenNotificationWidget.setHidden(false);
			hiddenNotificationWidget = null;
		}
	}

	private boolean isClueCasket(int itemId)
	{
		return itemId == ItemID.TRAIL_REWARD_CASKET_BEGINNER
			|| itemId == ItemID.TRAIL_REWARD_CASKET_EASY
			|| itemId == ItemID.TRAIL_REWARD_CASKET_MEDIUM
			|| itemId == ItemID.TRAIL_REWARD_CASKET_HARD
			|| itemId == ItemID.TRAIL_REWARD_CASKET_ELITE
			|| itemId == ItemID.TRAIL_REWARD_CASKET_MASTER;
	}

	private static int clueTier(int itemId)
	{
		switch (itemId)
		{
			case ItemID.TRAIL_REWARD_CASKET_BEGINNER: return 0;
			case ItemID.TRAIL_REWARD_CASKET_EASY: return 1;
			case ItemID.TRAIL_REWARD_CASKET_MEDIUM: return 2;
			case ItemID.TRAIL_REWARD_CASKET_HARD: return 3;
			case ItemID.TRAIL_REWARD_CASKET_ELITE: return 4;
			case ItemID.TRAIL_REWARD_CASKET_MASTER: return 5;
			default: return -1;
		}
	}

	private static List<Loot> lootFromContainer(ItemContainer container)
	{
		List<Loot> loot = new java.util.ArrayList<>();
		if (container == null)
		{
			return loot;
		}
		for (net.runelite.api.Item item : container.getItems())
		{
			if (item.getId() > 0 && item.getQuantity() > 0)
			{
				loot.add(new Loot(item.getId(), item.getQuantity()));
			}
		}
		return loot;
	}
}

package com.edjoe.cluecase;

import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;

/** Plays native Old School RuneScape sound effects through the game client. */
@Singleton
class ClueCaseSounds
{
	// Sound IDs currently have no generated gameval constants in the RuneLite API.
	private static final int CASKET_THUD = 2109;
	private static final int CLOCK_TICK_SINGLE = 4195;
	private static final int UNIQUE_DROP = 6765;

	private final Client client;
	private final ClueCaseConfig config;

	@Inject
	ClueCaseSounds(Client client, ClueCaseConfig config)
	{
		this.client = client;
		this.config = config;
	}

	void playDrop()
	{
		play(CASKET_THUD);
	}

	void playBounce()
	{
		play(CASKET_THUD);
	}

	void playTick()
	{
		play(CLOCK_TICK_SINGLE);
	}

	void playReward()
	{
		play(UNIQUE_DROP);
	}

	private void play(int soundId)
	{
		if (!config.soundEffects())
		{
			return;
		}
		// The single-argument API follows the in-game Sound Effects slider,
		// including its muted setting.
		client.playSoundEffect(soundId);
		// Layer a second native instance for a modest relative boost without
		// bypassing the game's Sound Effects volume or mute setting.
		client.playSoundEffect(soundId);
	}
}

package com.edjoe.cluecase;

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Arrays;
import java.util.Random;
import java.util.concurrent.ThreadLocalRandom;
import net.runelite.api.gameval.ItemID;

/** Generates teaser caskets from the flattened OSRS Wiki tables bundled in clue-loot.csv. */
final class ClueLootSimulator
{
	private static final String RESOURCE = "/clue-loot.csv";
	private static final double TABLE_RARITY_WEIGHT = 0.40;
	private static final double GE_VALUE_WEIGHT = 0.60;
	private static final int MAX_TARGET_GENERATION_ATTEMPTS = 1_000;
	private static final Map<String, Table> TABLES = loadTables();

	private ClueLootSimulator() {}

	static List<Loot> generate(int casketItemId)
	{
		return generate(casketItemId, null);
	}

	static List<Loot> generate(int casketItemId, LootRarity requestedRarity)
	{
		for (int attempt = 0; attempt < MAX_TARGET_GENERATION_ATTEMPTS; attempt++)
		{
			List<Loot> loot = generateCandidate(casketItemId, requestedRarity);
			if (requestedRarity == null || rarityFor(loot, casketItemId) == requestedRarity)
			{
				return loot;
			}
		}
		throw new IllegalStateException("Unable to generate " + requestedRarity
			+ " teaser contents after " + MAX_TARGET_GENERATION_ATTEMPTS + " attempts");
	}

	private static List<Loot> generateCandidate(int casketItemId, LootRarity requestedRarity)
	{
		Tier tier = tierFor(casketItemId);
		Table table = TABLES.get(tier.name);
		if (table == null || table.entries.isEmpty())
		{
			throw new IllegalStateException("No clue loot data loaded for " + tier.name);
		}
		ThreadLocalRandom random = ThreadLocalRandom.current();
		int rolls = random.nextInt(tier.minimumRolls, tier.maximumRolls + 1);
		Map<Integer, Integer> combined = new LinkedHashMap<>();
		LootRarity selectedRarity = requestedRarity == null
			? null : table.requireAvailableRarity(requestedRarity);
		for (int roll = 0; roll < rolls; roll++)
		{
			// Guarantee one reward from the requested band. Other rolls may be
			// more common, but never rarer, so the bundle retains that exact rarity.
			Entry entry = selectedRarity == null
				? table.pick(random.nextDouble(table.totalWeight))
				: table.pickForRarity(selectedRarity, roll == 0, random);
			int quantity = random.nextInt(entry.minimumQuantity, entry.maximumQuantity + 1);
			combined.merge(entry.itemId, quantity, Integer::sum);
		}
		List<Loot> loot = new ArrayList<>();
		combined.forEach((itemId, quantity) -> loot.add(new Loot(itemId, quantity)));
		return loot;
	}

	static LootRarity rarityFor(List<Loot> loot, int casketItemId)
	{
		Table table = TABLES.get(tierFor(casketItemId).name);
		LootRarity rarest = LootRarity.MIL_SPEC;
		long totalGeValue = 0L;
		for (Loot reward : loot)
		{
			LootRarity itemRarity = table.rarityByItem.getOrDefault(
				reward.getItemId(), LootRarity.MIL_SPEC);
			if (itemRarity.ordinal() > rarest.ordinal())
			{
				rarest = itemRarity;
			}
			long unitPrice = table.gePriceByItem.getOrDefault(reward.getItemId(), 0L);
			long itemValue;
			try
			{
				itemValue = Math.multiplyExact(unitPrice, (long) reward.getQuantity());
				totalGeValue = Math.addExact(totalGeValue, itemValue);
			}
			catch (ArithmeticException ignored)
			{
				totalGeValue = Long.MAX_VALUE;
			}
		}
		LootRarity valueFloor = table.rarityForTotalValue(totalGeValue);
		return valueFloor.ordinal() > rarest.ordinal() ? valueFloor : rarest;
	}

	static long[] valueThresholdsFor(int casketItemId)
	{
		Table table = TABLES.get(tierFor(casketItemId).name);
		return Arrays.copyOf(table.valueThresholds, table.valueThresholds.length);
	}

	private static Map<String, Table> loadTables()
	{
		Map<String, Table> tables = new HashMap<>();
		try (InputStream stream = ClueLootSimulator.class.getResourceAsStream(RESOURCE))
		{
			if (stream == null) { throw new IllegalStateException("Missing resource " + RESOURCE); }
			try (BufferedReader reader = new BufferedReader(new InputStreamReader(stream, StandardCharsets.UTF_8)))
			{
				reader.readLine();
				String line;
				while ((line = reader.readLine()) != null)
				{
					List<String> fields = parseCsvLine(line);
					if (fields.size() < 8) { continue; }
					Entry entry = new Entry(fields.get(1), Integer.parseInt(fields.get(2)),
						Integer.parseInt(fields.get(4)), Integer.parseInt(fields.get(5)),
						Double.parseDouble(fields.get(6)), Long.parseLong(fields.get(7)));
					tables.computeIfAbsent(fields.get(0), ignored -> new Table()).add(entry);
				}
			}
		}
		catch (IOException | NumberFormatException exception)
		{
			throw new IllegalStateException("Unable to load " + RESOURCE, exception);
		}
		for (Map.Entry<String, Table> loadedTable : tables.entrySet())
		{
			Table table = loadedTable.getValue();
			table.buildRarityBands();
			Tier tier = tierForName(loadedTable.getKey());
			table.buildValueThresholds(tier.minimumRolls, tier.maximumRolls,
				loadedTable.getKey().hashCode());
		}
		return tables;
	}

	private static List<String> parseCsvLine(String line)
	{
		List<String> fields = new ArrayList<>();
		StringBuilder field = new StringBuilder();
		boolean quoted = false;
		for (int index = 0; index < line.length(); index++)
		{
			char character = line.charAt(index);
			if (character == '"')
			{
				if (quoted && index + 1 < line.length() && line.charAt(index + 1) == '"')
				{
					field.append('"'); index++;
				}
				else { quoted = !quoted; }
			}
			else if (character == ',' && !quoted)
			{
				fields.add(field.toString()); field.setLength(0);
			}
			else { field.append(character); }
		}
		fields.add(field.toString());
		return fields;
	}

	private static Tier tierFor(int casketItemId)
	{
		switch (casketItemId)
		{
			case ItemID.TRAIL_REWARD_CASKET_BEGINNER: return new Tier("beginner", 1, 3);
			case ItemID.TRAIL_REWARD_CASKET_EASY: return new Tier("easy", 2, 4);
			case ItemID.TRAIL_REWARD_CASKET_MEDIUM: return new Tier("medium", 3, 5);
			case ItemID.TRAIL_REWARD_CASKET_HARD: return new Tier("hard", 4, 6);
			case ItemID.TRAIL_REWARD_CASKET_ELITE: return new Tier("elite", 4, 6);
			case ItemID.TRAIL_REWARD_CASKET_MASTER: return new Tier("master", 5, 7);
			default: return new Tier("hard", 4, 6);
		}
	}

	private static Tier tierForName(String name)
	{
		switch (name)
		{
			case "beginner": return new Tier(name, 1, 3);
			case "easy": return new Tier(name, 2, 4);
			case "medium": return new Tier(name, 3, 5);
			case "hard": return new Tier(name, 4, 6);
			case "elite": return new Tier(name, 4, 6);
			case "master": return new Tier(name, 5, 7);
			default: throw new IllegalArgumentException("Unknown clue tier " + name);
		}
	}

	private static final class Tier
	{
		private final String name; private final int minimumRolls; private final int maximumRolls;
		private Tier(String name, int minimumRolls, int maximumRolls)
		{
			this.name = name; this.minimumRolls = minimumRolls; this.maximumRolls = maximumRolls;
		}
	}

	private static final class Table
	{
		private final List<Entry> entries = new ArrayList<>();
		private final Map<Integer, Double> probabilityByItem = new HashMap<>();
		private final Map<Integer, String> sectionByItem = new HashMap<>();
		private final Map<Integer, Long> gePriceByItem = new HashMap<>();
		private final Map<Integer, LootRarity> rarityByItem = new HashMap<>();
		private final long[] valueThresholds = new long[4];
		private double totalWeight;
		private void add(Entry entry)
		{
			entries.add(entry);
			totalWeight += entry.weight;
			probabilityByItem.merge(entry.itemId, entry.weight, Double::sum);
			sectionByItem.putIfAbsent(entry.itemId, entry.section);
			gePriceByItem.put(entry.itemId, entry.gePrice);
		}
		private Entry pick(double target)
		{
			double cumulative = 0.0;
			for (Entry entry : entries)
			{
				cumulative += entry.weight;
				if (target < cumulative) { return entry; }
			}
			return entries.get(entries.size() - 1);
		}

		private LootRarity rarityOf(Entry entry)
		{
			return rarityByItem.getOrDefault(entry.itemId, LootRarity.MIL_SPEC);
		}

		private void buildRarityBands()
		{
			Map<String, List<Integer>> uniqueItemsBySection = new HashMap<>();
			List<Integer> ordinaryItems = new ArrayList<>();
			for (Map.Entry<Integer, Double> item : probabilityByItem.entrySet())
			{
				String section = sectionByItem.get(item.getKey());
				if (isMegaRare(section))
				{
					continue;
				}
				List<Integer> items = isClueUnique(section)
					? uniqueItemsBySection.computeIfAbsent(section, ignored -> new ArrayList<>())
					: ordinaryItems;
				items.add(item.getKey());
			}
			assignRelativeRarities(ordinaryItems, false);
			for (List<Integer> items : uniqueItemsBySection.values())
			{
				assignRelativeRarities(items, true);
			}

			for (Map.Entry<Integer, Double> item : probabilityByItem.entrySet())
			{
				String section = sectionByItem.get(item.getKey());
				if (isMegaRare(section))
				{
					rarityByItem.put(item.getKey(), LootRarity.RARE_SPECIAL);
					continue;
				}
			}
		}

		private void assignRelativeRarities(List<Integer> itemIds, boolean allowGold)
		{
			if (itemIds.isEmpty()) { return; }
			List<Double> probabilityLevels = new ArrayList<>();
			List<Long> priceLevels = new ArrayList<>();
			for (int itemId : itemIds)
			{
				double probability = probabilityByItem.get(itemId);
				long price = gePriceByItem.getOrDefault(itemId, 0L);
				if (!probabilityLevels.contains(probability)) { probabilityLevels.add(probability); }
				if (!priceLevels.contains(price)) { priceLevels.add(price); }
			}
			probabilityLevels.sort(java.util.Collections.reverseOrder());
			java.util.Collections.sort(priceLevels);
			Map<Integer, Double> scores = new HashMap<>();
			List<Double> scoreLevels = new ArrayList<>();
			for (int itemId : itemIds)
			{
				double probabilityRank = normalizedRank(probabilityLevels,
					probabilityByItem.get(itemId));
				double priceRank = normalizedRank(priceLevels,
					gePriceByItem.getOrDefault(itemId, 0L));
				double score = probabilityRank * TABLE_RARITY_WEIGHT
					+ priceRank * GE_VALUE_WEIGHT;
				scores.put(itemId, score);
				if (!scoreLevels.contains(score)) { scoreLevels.add(score); }
			}
			java.util.Collections.sort(scoreLevels);
			for (int itemId : itemIds)
			{
				double relativeRank = normalizedRank(scoreLevels, scores.get(itemId));
				rarityByItem.put(itemId, rarityForRelativeRank(relativeRank, allowGold));
			}
		}

		private static double normalizedRank(List<?> levels, Object value)
		{
			return levels.size() <= 1 ? 1.0 : levels.indexOf(value) / (double) (levels.size() - 1);
		}

		private static LootRarity rarityForRelativeRank(double relativeRank, boolean allowGold)
		{
			LootRarity[] bands = allowGold
				? new LootRarity[]{LootRarity.CLASSIFIED, LootRarity.COVERT, LootRarity.RARE_SPECIAL}
				: new LootRarity[]{LootRarity.MIL_SPEC, LootRarity.RESTRICTED};
			int band = Math.min(bands.length - 1,
				(int) Math.floor(relativeRank * bands.length));
			return bands[band];
		}

		private static boolean isClueUnique(String section)
		{
			return section != null && section.toLowerCase().contains("clue uniques");
		}

		private static boolean isMegaRare(String section)
		{
			return section != null && section.toLowerCase().contains("mega");
		}

		private void buildValueThresholds(int minimumRolls, int maximumRolls, int seed)
		{
			final int samples = 100_000;
			long[] values = new long[samples];
			Random random = new Random(0x43415345L ^ seed);
			for (int sample = 0; sample < samples; sample++)
			{
				int rolls = minimumRolls + random.nextInt(maximumRolls - minimumRolls + 1);
				long total = 0L;
				for (int roll = 0; roll < rolls; roll++)
				{
					Entry entry = pick(random.nextDouble() * totalWeight);
					int quantity = entry.minimumQuantity
						+ random.nextInt(entry.maximumQuantity - entry.minimumQuantity + 1);
					total += entry.gePrice * (long) quantity;
				}
				values[sample] = total;
			}
			Arrays.sort(values);
			valueThresholds[0] = percentile(values, 0.79923);
			valueThresholds[1] = percentile(values, 0.95908);
			valueThresholds[2] = percentile(values, 0.99105);
			valueThresholds[3] = percentile(values, 0.99744);
		}

		private static long percentile(long[] sortedValues, double percentile)
		{
			return sortedValues[(int) Math.floor(percentile * (sortedValues.length - 1))];
		}

		private LootRarity rarityForTotalValue(long totalGeValue)
		{
			if (totalGeValue >= valueThresholds[3]) { return LootRarity.RARE_SPECIAL; }
			if (totalGeValue >= valueThresholds[2]) { return LootRarity.COVERT; }
			if (totalGeValue >= valueThresholds[1]) { return LootRarity.CLASSIFIED; }
			if (totalGeValue >= valueThresholds[0]) { return LootRarity.RESTRICTED; }
			return LootRarity.MIL_SPEC;
		}

		private LootRarity requireAvailableRarity(LootRarity requested)
		{
			for (Entry entry : entries)
			{
				if (rarityOf(entry) == requested)
				{
					return requested;
				}
			}
			throw new IllegalStateException("No " + requested + " rewards in clue table");
		}

		private Entry pickForRarity(LootRarity rarity, boolean exact, ThreadLocalRandom random)
		{
			double eligibleWeight = 0.0;
			for (Entry entry : entries)
			{
				LootRarity entryRarity = rarityOf(entry);
				if ((exact && entryRarity == rarity)
					|| (!exact && entryRarity.ordinal() <= rarity.ordinal()))
				{
					eligibleWeight += entry.weight;
				}
			}

			double target = random.nextDouble(eligibleWeight);
			double cumulative = 0.0;
			Entry fallback = null;
			for (Entry entry : entries)
			{
				LootRarity entryRarity = rarityOf(entry);
				if ((exact && entryRarity == rarity)
					|| (!exact && entryRarity.ordinal() <= rarity.ordinal()))
				{
					fallback = entry;
					cumulative += entry.weight;
					if (target < cumulative) { return entry; }
				}
			}
			return fallback;
		}
	}

	private static final class Entry
	{
		private final String section; private final int itemId; private final int minimumQuantity; private final int maximumQuantity; private final double weight; private final long gePrice;
		private Entry(String section, int itemId, int minimumQuantity, int maximumQuantity, double weight, long gePrice)
		{
			this.section = section; this.itemId = itemId; this.minimumQuantity = minimumQuantity;
			this.maximumQuantity = maximumQuantity; this.weight = weight;
			this.gePrice = gePrice;
		}
	}
}

package com.edjoe.cluecase;

public enum InteractionControl
{
	BOTH("Space or left-click", true, true),
	SPACE_ONLY("Space only", true, false),
	LEFT_CLICK_ONLY("Left-click only", false, true);

	private final String label;
	private final boolean space;
	private final boolean leftClick;

	InteractionControl(String label, boolean space, boolean leftClick)
	{
		this.label = label;
		this.space = space;
		this.leftClick = leftClick;
	}

	public boolean allowsSpace() { return space; }

	public boolean allowsLeftClick() { return leftClick; }

	@Override
	public String toString() { return label; }
}

package com.edjoe.cluecase;

final class Loot
{
	private final int itemId;
	private final int quantity;

	Loot(int itemId, int quantity)
	{
		this.itemId = itemId;
		this.quantity = quantity;
	}

	int getItemId()
	{
		return itemId;
	}

	int getQuantity()
	{
		return quantity;
	}
}

package com.edjoe.cluecase;

import java.awt.Color;

enum LootRarity
{
	CONSUMER(new Color(176, 195, 217)),
	INDUSTRIAL(new Color(94, 152, 217)),
	MIL_SPEC(new Color(75, 105, 255)),
	RESTRICTED(new Color(136, 71, 255)),
	CLASSIFIED(new Color(211, 44, 230)),
	COVERT(new Color(235, 75, 75)),
	RARE_SPECIAL(new Color(255, 205, 54));

	private final Color color;

	LootRarity(Color color)
	{
		this.color = color;
	}

	Color getColor()
	{
		return color;
	}
}

